* Ran the following batch insert SP:

{noformat}DROP PROCEDURE IF EXISTS insert_batch_in_loop;

DELIMITER $$
CREATE PROCEDURE insert_batch_in_loop()
BEGIN

  DECLARE v_min_id BIGINT DEFAULT 0;
  DECLARE v_max_id BIGINT DEFAULT 0;
  DECLARE v_batch_size INT DEFAULT 10000;

  DECLARE v_sleep_cnt INT DEFAULT 0;
  DECLARE v_sleep_after INT DEFAULT 1000;
  DECLARE v_sleep_time INT DEFAULT 5;

  SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM `taxify_payment`.`payment_method_user`;
  SELECT v_min_id, v_max_id, v_batch_size;

  WHILE v_min_id <= v_max_id DO

    INSERT INTO taxify_payment.card_migration (payment_user_id, payment_method_user_id)
    SELECT payment_user_id, id as payment_method_user_id 
    FROM `taxify_payment`.`payment_method_user` 
    WHERE
       ((payment_method_type = 'adyen' AND created < '2021-05-25') OR
        (payment_method_type = 'zooz' AND created < '2021-06-18'))
        AND is_deleted = 0   
        AND is_hidden = 0   
        AND expires > '2021-08-01'
        AND id >= v_min_id AND id < v_min_id + v_batch_size;

    SET v_min_id = v_min_id + v_batch_size;

    SET v_sleep_cnt = v_sleep_cnt + 1;
    SELECT v_min_id, v_sleep_cnt, v_sleep_after;

    IF v_sleep_cnt > v_sleep_after THEN
      SELECT CONCAT('Last id processed: ', v_min_id);
      SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
      SELECT SLEEP(v_sleep_time);
      SET v_sleep_cnt = 0;
    END IF;

  END WHILE;
END;
$$
DELIMITER ;{noformat}
